#import "MapController.h"
#import <MapKit/MapKit.h>
#import <notify.h>
static NSString *const path=@"/var/mobile/Library/Preferences/com.xtieume.gpsnav.plist";
@interface MapController () <MKMapViewDelegate, UISearchBarDelegate>
@property MKMapView *map;
@property UISegmentedControl *mode;
@property UISwitch *enabled;
@property UILabel *status;
@property NSMutableDictionary *config;
@property NSMutableArray *bookmarks, *routes, *history;
@property MKPointAnnotation *selection, *current, *start, *end;
@property MKPolyline *line;
@property MKDirections *directions;
@property NSUInteger routeGeneration;
@property int latToken, lonToken, flagsToken;
@end
@implementation MapController
- (void)viewDidLoad {
 [super viewDidLoad]; self.title=@"GPSNav"; self.view.backgroundColor=UIColor.systemBackgroundColor;
 self.config=[NSMutableDictionary dictionaryWithContentsOfFile:path] ?: NSMutableDictionary.new;
 NSDictionary *defaults=@{@"latitude":@10.7769,@"longitude":@106.7009,@"mode":@"fixed",@"speed":@40,@"radius":@500,@"interval":@30,@"loop":@NO,@"enabled":@NO,@"revision":NSUUID.UUID.UUIDString,@"transport":@"automobile"};
 for (NSString *key in defaults) if (!self.config[key]) self.config[key]=defaults[key];
 self.bookmarks=[self.config[@"bookmarks"] mutableCopy] ?: NSMutableArray.new; self.routes=[self.config[@"savedRoutes"] mutableCopy] ?: NSMutableArray.new; self.history=[self.config[@"history"] mutableCopy] ?: NSMutableArray.new;
 notify_register_check("com.xtieume.gpsnav.lat",&_latToken); notify_register_check("com.xtieume.gpsnav.lon",&_lonToken); notify_register_check("com.xtieume.gpsnav.flags",&_flagsToken);
 UIStackView *root=[[UIStackView alloc] init]; root.axis=UILayoutConstraintAxisVertical; root.translatesAutoresizingMaskIntoConstraints=NO; [self.view addSubview:root]; [NSLayoutConstraint activateConstraints:@[[root.topAnchor constraintEqualToAnchor:self.view.safeAreaLayoutGuide.topAnchor],[root.bottomAnchor constraintEqualToAnchor:self.view.safeAreaLayoutGuide.bottomAnchor],[root.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor],[root.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor]]];
 UISearchBar *search=UISearchBar.new; search.placeholder=@"Search places"; search.delegate=self; [root addArrangedSubview:search];
 self.map=MKMapView.new; self.map.delegate=self; [root addArrangedSubview:self.map]; [self.map.heightAnchor constraintGreaterThanOrEqualToConstant:180].active=YES;
 CLLocationCoordinate2D coord=CLLocationCoordinate2DMake([self.config[@"latitude"] doubleValue],[self.config[@"longitude"] doubleValue]); [self.map setRegion:MKCoordinateRegionMakeWithDistance(coord,5000,5000) animated:NO];
 UITapGestureRecognizer *tap=[[UITapGestureRecognizer alloc] initWithTarget:self action:@selector(mapTap:)]; tap.delegate=(id)self; [self.map addGestureRecognizer:tap]; UILongPressGestureRecognizer *press=[[UILongPressGestureRecognizer alloc] initWithTarget:self action:@selector(mapTap:)]; [self.map addGestureRecognizer:press];
 UIScrollView *scroll=UIScrollView.new; [root addArrangedSubview:scroll]; [scroll.heightAnchor constraintEqualToConstant:215].active=YES;
 UIStackView *controls=UIStackView.new; controls.axis=UILayoutConstraintAxisVertical; controls.spacing=5; controls.layoutMargins=UIEdgeInsetsMake(6,12,6,12); controls.layoutMarginsRelativeArrangement=YES; controls.translatesAutoresizingMaskIntoConstraints=NO; [scroll addSubview:controls]; [NSLayoutConstraint activateConstraints:@[[controls.topAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.topAnchor],[controls.bottomAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.bottomAnchor],[controls.leadingAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.leadingAnchor],[controls.trailingAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.trailingAnchor],[controls.widthAnchor constraintEqualToAnchor:scroll.frameLayoutGuide.widthAnchor]]];
 self.mode=[[UISegmentedControl alloc] initWithItems:@[@"Fixed",@"Route",@"Random"]]; self.mode.selectedSegmentIndex=[self.config[@"mode"] isEqual:@"route"]?1:([self.config[@"mode"] isEqual:@"random"]?2:0); [self.mode addTarget:self action:@selector(modeChanged) forControlEvents:UIControlEventValueChanged]; [controls addArrangedSubview:self.mode];
 UIStackView *row= [self row]; UILabel *label=UILabel.new; label.text=@"Spoof location"; [row addArrangedSubview:label]; self.enabled=UISwitch.new; self.enabled.on=[self.config[@"enabled"] boolValue]; [self.enabled addTarget:self action:@selector(enabledChanged) forControlEvents:UIControlEventValueChanged]; [row addArrangedSubview:self.enabled]; [controls addArrangedSubview:row];
 self.status=UILabel.new; self.status.font=[UIFont systemFontOfSize:12]; self.status.numberOfLines=2; [controls addArrangedSubview:self.status];
 [controls addArrangedSubview:[self buttons:@[@"Bookmarks",@"Routes",@"Search history"] selectors:@[@"bookmarksMenu",@"routesMenu",@"historyMenu"]]];
 [controls addArrangedSubview:[self buttons:@[@"Speed / route",@"Random",@"Settings"] selectors:@[@"routeOptions",@"randomOptions",@"settings"]]];
 self.current=MKPointAnnotation.new; self.current.title=@"Engine position"; [self.map addAnnotation:self.current]; [self restoreRoute]; [self updateSelection:coord]; [self poll]; [NSTimer scheduledTimerWithTimeInterval:1 target:self selector:@selector(poll) userInfo:nil repeats:YES];
}
- (UIStackView *)row { UIStackView *r=UIStackView.new; r.axis=UILayoutConstraintAxisHorizontal; r.distribution=UIStackViewDistributionEqualSpacing; r.alignment=UIStackViewAlignmentCenter; r.spacing=5; return r; }
- (UIStackView *)buttons:(NSArray *)titles selectors:(NSArray *)selectors { UIStackView *r=[self row]; r.distribution=UIStackViewDistributionFillEqually; for (NSUInteger i=0;i<titles.count;i++) { UIButton *b=[UIButton buttonWithType:UIButtonTypeSystem]; [b setTitle:titles[i] forState:UIControlStateNormal]; b.titleLabel.font=[UIFont systemFontOfSize:13]; [b addTarget:self action:NSSelectorFromString(selectors[i]) forControlEvents:UIControlEventTouchUpInside]; [r addArrangedSubview:b]; } return r; }
- (void)save:(BOOL)reset { if (reset) self.config[@"revision"]=NSUUID.UUID.UUIDString; self.config[@"bookmarks"]=self.bookmarks; self.config[@"savedRoutes"]=self.routes; self.config[@"history"]=self.history; if (![self.config writeToFile:path atomically:YES]) { [self message:@"Could not save settings. Check jailbreak permissions."]; return; } notify_post("com.xtieume.gpsnav.reload"); }
- (void)message:(NSString *)text { UIAlertController *a=[UIAlertController alertControllerWithTitle:@"GPSNav" message:text preferredStyle:UIAlertControllerStyleAlert]; [a addAction:[UIAlertAction actionWithTitle:@"OK" style:UIAlertActionStyleCancel handler:nil]]; [self presentViewController:a animated:YES completion:nil]; }
- (void)poll { uint64_t flags=0,a=0,b=0; notify_get_state(self.flagsToken,&flags); notify_get_state(self.latToken,&a); notify_get_state(self.lonToken,&b); double lat,lon; memcpy(&lat,&a,8); memcpy(&lon,&b,8); if ((flags&1) && CLLocationCoordinate2DIsValid(CLLocationCoordinate2DMake(lat,lon))) self.current.coordinate=CLLocationCoordinate2DMake(lat,lon); self.status.text=[NSString stringWithFormat:@"%@ · %.5f, %.5f · Tap map to select",(flags&1)?@"Engine on":@"Engine off",lat,lon]; }
- (void)updateSelection:(CLLocationCoordinate2D)c { if (!self.selection) { self.selection=MKPointAnnotation.new; self.selection.title=@"Selected / random center"; [self.map addAnnotation:self.selection]; } self.selection.coordinate=c; }
- (void)modeChanged { self.config[@"mode"]=@[@"fixed",@"route",@"random"][(NSUInteger)self.mode.selectedSegmentIndex]; [self save:YES]; }
- (void)enabledChanged { if (self.enabled.on && self.mode.selectedSegmentIndex==1 && [self.config[@"route"] count]<2) { self.enabled.on=NO; [self message:@"Select two points and wait for a route first."]; return; } self.config[@"enabled"]=@(self.enabled.on); [self save:NO]; }
- (void)mapTap:(UIGestureRecognizer *)gesture { if ([gesture isKindOfClass:UILongPressGestureRecognizer.class] && gesture.state!=UIGestureRecognizerStateBegan) return; if ([gesture isKindOfClass:UITapGestureRecognizer.class] && gesture.state!=UIGestureRecognizerStateEnded) return; CLLocationCoordinate2D c=[self.map convertPoint:[gesture locationInView:self.map] toCoordinateFromView:self.map]; [self choose:c]; }
- (void)choose:(CLLocationCoordinate2D)c { if (self.mode.selectedSegmentIndex==1) { if (!self.start || self.end) { [self clearRoute]; self.start=MKPointAnnotation.new; self.start.title=@"A"; self.start.coordinate=c; [self.map addAnnotation:self.start]; self.config[@"latitude"]=@(c.latitude); self.config[@"longitude"]=@(c.longitude); [self save:YES]; } else { self.end=MKPointAnnotation.new; self.end.title=@"B"; self.end.coordinate=c; [self.map addAnnotation:self.end]; [self fetchRoute]; } } else { self.config[@"latitude"]=@(c.latitude); self.config[@"longitude"]=@(c.longitude); [self updateSelection:c]; [self save:YES]; } }
- (void)clearRoute { self.routeGeneration++; [self.directions cancel]; if (self.start) [self.map removeAnnotation:self.start]; if (self.end) [self.map removeAnnotation:self.end]; if (self.line) [self.map removeOverlay:self.line]; self.start=nil; self.end=nil; self.line=nil; [self.config removeObjectForKey:@"route"]; }
- (void)fetchRoute { NSUInteger generation=++self.routeGeneration; [self.directions cancel]; MKDirectionsRequest *request=MKDirectionsRequest.new; request.source=[[MKMapItem alloc] initWithPlacemark:[[MKPlacemark alloc] initWithCoordinate:self.start.coordinate]]; request.destination=[[MKMapItem alloc] initWithPlacemark:[[MKPlacemark alloc] initWithCoordinate:self.end.coordinate]]; request.transportType=[self.config[@"transport"] isEqual:@"walking"]?MKDirectionsTransportTypeWalking:MKDirectionsTransportTypeAutomobile; self.directions=[[MKDirections alloc] initWithRequest:request]; self.status.text=@"Loading route…"; [self.directions calculateDirectionsWithCompletionHandler:^(MKDirectionsResponse *response, NSError *error) { if (generation!=self.routeGeneration) return; MKRoute *route=response.routes.firstObject; if (!route) { [self message:error.localizedDescription ?: @"No route found."]; return; } if (self.line) [self.map removeOverlay:self.line]; self.line=route.polyline; [self.map addOverlay:self.line]; NSUInteger count=self.line.pointCount; CLLocationCoordinate2D *coords=calloc(count,sizeof(*coords)); [self.line getCoordinates:coords range:NSMakeRange(0,count)]; NSMutableArray *points=NSMutableArray.new; for (NSUInteger i=0;i<count;i++) [points addObject:@[@(coords[i].latitude),@(coords[i].longitude)]]; free(coords); self.config[@"route"]=points; [self save:YES]; }]; }
- (void)restoreRoute { NSArray *points=self.config[@"route"]; if (points.count<2) return; CLLocationCoordinate2D *coords=calloc(points.count,sizeof(*coords)); for (NSUInteger i=0;i<points.count;i++) coords[i]=CLLocationCoordinate2DMake([points[i][0] doubleValue],[points[i][1] doubleValue]); self.start=MKPointAnnotation.new; self.start.title=@"A"; self.start.coordinate=coords[0]; self.end=MKPointAnnotation.new; self.end.title=@"B"; self.end.coordinate=coords[points.count-1]; [self.map addAnnotations:@[self.start,self.end]]; self.line=[MKPolyline polylineWithCoordinates:coords count:points.count]; [self.map addOverlay:self.line]; free(coords); }
- (MKOverlayRenderer *)mapView:(MKMapView *)mapView rendererForOverlay:(id<MKOverlay>)overlay { MKPolylineRenderer *r=[[MKPolylineRenderer alloc] initWithPolyline:(MKPolyline *)overlay]; r.strokeColor=UIColor.systemBlueColor; r.lineWidth=4; return r; }
- (void)searchBarSearchButtonClicked:(UISearchBar *)bar { NSString *query=[bar.text stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet]; if (!query.length) return; [bar resignFirstResponder]; [self.history removeObject:query]; [self.history insertObject:query atIndex:0]; while (self.history.count>20) [self.history removeLastObject]; [self save:NO]; MKLocalSearchRequest *req=MKLocalSearchRequest.new; req.naturalLanguageQuery=query; req.region=self.map.region; [[[MKLocalSearch alloc] initWithRequest:req] startWithCompletionHandler:^(MKLocalSearchResponse *response,NSError *error){ if (!response.mapItems.count) { [self message:error.localizedDescription ?: @"No places found."]; return; } UIAlertController *a=[UIAlertController alertControllerWithTitle:@"Search results" message:nil preferredStyle:UIAlertControllerStyleActionSheet]; for (MKMapItem *item in response.mapItems) [a addAction:[UIAlertAction actionWithTitle:item.name ?: @"Place" style:UIAlertActionStyleDefault handler:^(UIAlertAction *action){ CLLocationCoordinate2D c=item.placemark.coordinate; [self.map setCenterCoordinate:c animated:YES]; [self choose:c]; }]]; [a addAction:[UIAlertAction actionWithTitle:@"Cancel" style:UIAlertActionStyleCancel handler:nil]]; a.popoverPresentationController.sourceView=self.view; a.popoverPresentationController.sourceRect=CGRectMake(CGRectGetMidX(self.view.bounds),CGRectGetMidY(self.view.bounds),1,1); [self presentViewController:a animated:YES completion:nil]; }]; }
- (void)sheet:(NSString *)title actions:(NSArray<UIAlertAction *> *)actions { UIAlertController *a=[UIAlertController alertControllerWithTitle:title message:nil preferredStyle:UIAlertControllerStyleActionSheet]; for (UIAlertAction *action in actions) [a addAction:action]; [a addAction:[UIAlertAction actionWithTitle:@"Cancel" style:UIAlertActionStyleCancel handler:nil]]; a.popoverPresentationController.sourceView=self.view; a.popoverPresentationController.sourceRect=CGRectMake(CGRectGetMidX(self.view.bounds),CGRectGetMidY(self.view.bounds),1,1); [self presentViewController:a animated:YES completion:nil]; }
- (void)namePrompt:(NSString *)title completion:(void (^)(NSString *))completion { UIAlertController *a=[UIAlertController alertControllerWithTitle:title message:nil preferredStyle:UIAlertControllerStyleAlert]; [a addTextFieldWithConfigurationHandler:^(UITextField *f){ f.placeholder=@"Name"; }]; [a addAction:[UIAlertAction actionWithTitle:@"Cancel" style:UIAlertActionStyleCancel handler:nil]]; [a addAction:[UIAlertAction actionWithTitle:@"Save" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){ NSString *name=[a.textFields.firstObject.text stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet]; if (name.length) completion(name); }]]; [self presentViewController:a animated:YES completion:nil]; }
- (void)bookmarksMenu { NSMutableArray *actions=NSMutableArray.new; [actions addObject:[UIAlertAction actionWithTitle:@"Save selected location" style:UIAlertActionStyleDefault handler:^(UIAlertAction *a){ [self namePrompt:@"Save bookmark" completion:^(NSString *name){ [self.bookmarks addObject:@{@"name":name,@"lat":self.config[@"latitude"],@"lon":self.config[@"longitude"]}]; [self save:NO]; }]; }]]; for (NSDictionary *entry in [self.bookmarks copy]) [actions addObject:[UIAlertAction actionWithTitle:entry[@"name"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *a){ [self sheet:entry[@"name"] actions:@[[UIAlertAction actionWithTitle:@"Apply" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){ CLLocationCoordinate2D c=CLLocationCoordinate2DMake([entry[@"lat"] doubleValue],[entry[@"lon"] doubleValue]); [self.map setCenterCoordinate:c animated:YES]; [self choose:c]; }],[UIAlertAction actionWithTitle:@"Delete" style:UIAlertActionStyleDestructive handler:^(UIAlertAction *x){ [self.bookmarks removeObject:entry]; [self save:NO]; }]]]; }]]; [self sheet:@"Bookmarks" actions:actions]; }
- (void)routesMenu { NSMutableArray *actions=NSMutableArray.new; [actions addObject:[UIAlertAction actionWithTitle:@"Save current route" style:UIAlertActionStyleDefault handler:^(UIAlertAction *a){ NSArray *route=self.config[@"route"]; if (route.count<2) { [self message:@"Select a route first."]; return; } [self namePrompt:@"Save route" completion:^(NSString *name){ [self.routes addObject:@{@"name":name,@"route":route}]; [self save:NO]; }]; }]]; for (NSDictionary *entry in [self.routes copy]) [actions addObject:[UIAlertAction actionWithTitle:entry[@"name"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *a){ [self sheet:entry[@"name"] actions:@[[UIAlertAction actionWithTitle:@"Apply" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){ [self clearRoute]; self.config[@"route"]=entry[@"route"]; NSArray *first=[entry[@"route"] firstObject]; self.config[@"latitude"]=first[0]; self.config[@"longitude"]=first[1]; self.mode.selectedSegmentIndex=1; self.config[@"mode"]=@"route"; [self restoreRoute]; [self.map setVisibleMapRect:self.line.boundingMapRect edgePadding:UIEdgeInsetsMake(40,40,40,40) animated:YES]; [self save:YES]; }],[UIAlertAction actionWithTitle:@"Delete" style:UIAlertActionStyleDestructive handler:^(UIAlertAction *x){ [self.routes removeObject:entry]; [self save:NO]; }]]]; }]]; [self sheet:@"Saved routes" actions:actions]; }
- (void)historyMenu { NSMutableArray *actions=NSMutableArray.new; for (NSString *entry in [self.history copy]) [actions addObject:[UIAlertAction actionWithTitle:entry style:UIAlertActionStyleDefault handler:^(UIAlertAction *a){ UISearchBar *bar=UISearchBar.new; bar.text=entry; [self searchBarSearchButtonClicked:bar]; }]]; if (self.history.count) [actions addObject:[UIAlertAction actionWithTitle:@"Clear history" style:UIAlertActionStyleDestructive handler:^(UIAlertAction *a){ [self.history removeAllObjects]; [self save:NO]; }]]; [self sheet:@"Search history" actions:actions]; }
- (void)numberPrompt:(NSString *)title value:(double)value completion:(void (^)(double))completion { UIAlertController *a=[UIAlertController alertControllerWithTitle:title message:@"Enter a positive number" preferredStyle:UIAlertControllerStyleAlert]; [a addTextFieldWithConfigurationHandler:^(UITextField *f){ f.keyboardType=UIKeyboardTypeDecimalPad; f.text=[NSString stringWithFormat:@"%g",value]; }]; [a addAction:[UIAlertAction actionWithTitle:@"Cancel" style:UIAlertActionStyleCancel handler:nil]]; [a addAction:[UIAlertAction actionWithTitle:@"Save" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){ double n=a.textFields.firstObject.text.doubleValue; if (isfinite(n) && n>0) completion(n); else [self message:@"Enter a positive number."]; }]]; [self presentViewController:a animated:YES completion:nil]; }
- (void)routeOptions { NSMutableArray *actions=NSMutableArray.new; for (NSNumber *speed in @[@5,@20,@40,@60,@80,@120]) [actions addObject:[UIAlertAction actionWithTitle:[NSString stringWithFormat:@"%@ km/h",speed] style:UIAlertActionStyleDefault handler:^(UIAlertAction *a){ self.config[@"speed"]=speed; [self save:NO]; }]]; [actions addObject:[UIAlertAction actionWithTitle:@"Custom speed" style:UIAlertActionStyleDefault handler:^(UIAlertAction *a){ [self numberPrompt:@"Speed (km/h)" value:[self.config[@"speed"] doubleValue] completion:^(double n){ self.config[@"speed"]=@(n); [self save:NO]; }]; }]]; [actions addObject:[UIAlertAction actionWithTitle:[self.config[@"loop"] boolValue]?@"Reverse loop: On (tap to turn off)":@"Reverse loop: Off (tap to turn on)" style:UIAlertActionStyleDefault handler:^(UIAlertAction *a){ self.config[@"loop"]=@(![self.config[@"loop"] boolValue]); [self save:NO]; }]]; [actions addObject:[UIAlertAction actionWithTitle:[self.config[@"transport"] isEqual:@"walking"]?@"Transport: Walking (switch to driving)":@"Transport: Driving (switch to walking)" style:UIAlertActionStyleDefault handler:^(UIAlertAction *a){ self.config[@"transport"]=[self.config[@"transport"] isEqual:@"walking"]?@"automobile":@"walking"; if (self.start && self.end) [self fetchRoute]; [self save:NO]; }]]; [actions addObject:[UIAlertAction actionWithTitle:@"Clear route" style:UIAlertActionStyleDestructive handler:^(UIAlertAction *a){ [self clearRoute]; if (self.mode.selectedSegmentIndex==1) { self.enabled.on=NO; self.config[@"enabled"]=@NO; } [self save:YES]; }]]; [self sheet:@"Route options" actions:actions]; }
- (void)randomOptions { [self sheet:@"Random mode" actions:@[[UIAlertAction actionWithTitle:[NSString stringWithFormat:@"Radius: %@ m",self.config[@"radius"]] style:UIAlertActionStyleDefault handler:^(UIAlertAction *a){ [self numberPrompt:@"Radius (meters)" value:[self.config[@"radius"] doubleValue] completion:^(double n){ self.config[@"radius"]=@(n); [self save:NO]; }]; }],[UIAlertAction actionWithTitle:[NSString stringWithFormat:@"Interval: %@ s",self.config[@"interval"]] style:UIAlertActionStyleDefault handler:^(UIAlertAction *a){ [self numberPrompt:@"Interval (seconds)" value:[self.config[@"interval"] doubleValue] completion:^(double n){ self.config[@"interval"]=@(n); [self save:NO]; }]; }]]]; }
- (void)settings { [self sheet:@"Settings" actions:@[[UIAlertAction actionWithTitle:@"Blacklist bundle IDs" style:UIAlertActionStyleDefault handler:^(UIAlertAction *a){ [self blacklist]; }],[UIAlertAction actionWithTitle:@"About" style:UIAlertActionStyleDefault handler:^(UIAlertAction *a){ [self message:@"GPSNav 1.0\nBy Tieu Me\nSimulated locations for jailbroken iOS. Blacklisted apps may require a restart; sandbox restrictions can prevent the blacklist being read."]; }]]]; }
- (void)blacklist { UIAlertController *a=[UIAlertController alertControllerWithTitle:@"Blacklist" message:@"One bundle ID per line. Restart affected apps after changes." preferredStyle:UIAlertControllerStyleAlert]; [a addTextFieldWithConfigurationHandler:^(UITextField *f){ f.placeholder=@"com.example.app, com.example.other"; f.text=[(self.config[@"blacklist"] ?: @[]) componentsJoinedByString:@", "]; f.autocapitalizationType=UITextAutocapitalizationTypeNone; f.autocorrectionType=UITextAutocorrectionTypeNo; }]; [a addAction:[UIAlertAction actionWithTitle:@"Cancel" style:UIAlertActionStyleCancel handler:nil]]; [a addAction:[UIAlertAction actionWithTitle:@"Save" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){ NSMutableArray *list=NSMutableArray.new; NSCharacterSet *separators=[NSCharacterSet characterSetWithCharactersInString:@",\n"]; for (NSString *part in [a.textFields.firstObject.text componentsSeparatedByCharactersInSet:separators]) { NSString *s=[part stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet]; if (s.length && ![list containsObject:s]) [list addObject:s]; } self.config[@"blacklist"]=list; [self save:NO]; }]]; [self presentViewController:a animated:YES completion:nil]; }
@end
